{
  "findings": [
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 Bucket Access Logging Not Enabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have access logging enabled, which prevents tracking of requests made to the bucket for security auditing and troubleshooting purposes."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 Bucket Versioning Disabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "LOW",
      "explanation": "Versioning is not enabled on the S3 bucket. For a backend state file, versioning provides protection against accidental deletion or overwriting of state files."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 Bucket Encryption Using KMS Not Configured",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "HIGH",
      "explanation": "The bucket does not specify server-side encryption configuration. Terraform state files often contain sensitive data (secrets, IPs) and should be encrypted at rest using SSE-KMS or SSE-S3 explicitly."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"changeme_aws_s3_bucket_backend_simple\" {\n  force_destroy = true\n  bucket        = \"changeme-${random_id.changeme_backends_s3_bucket_name.hex}\"\n}\n\nresource \"aws_s3_bucket_versioning\" \"changeme_aws_s3_bucket_backend_simple\" {\n  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id\n  versioning_configuration {\n    status = \"Enabled\"\n  }\n}\n\nresource \"aws_s3_bucket_server_side_encryption_configuration\" \"changeme_aws_s3_bucket_backend_simple\" {\n  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id\n  rule {\n    apply_server_side_encryption_by_default {\n      sse_algorithm = \"AES256\"\n    }\n  }\n}\n\nresource \"aws_s3_bucket_logging\" \"changeme_aws_s3_bucket_backend_simple\" {\n  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id\n  target_bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id\n  target_prefix = \"log/\"\n}",
  "fix_summary": "Added separate resources for `aws_s3_bucket_versioning`, `aws_s3_bucket_server_side_encryption_configuration`, and `aws_s3_bucket_logging` to enable versioning, enforce AES256 encryption at rest, and configure access logging for the S3 bucket."
}
